import dev.jayms.net.structure.StructurePackage;
import java.io.*;
import java.nio.file.*;
public class CheckImportGates {
 public static void main(String[] args)throws Exception {
  for(String fixture:new String[]{"city","maximum"}) {
   Path source=Path.of("target/structure-fixtures/"+fixture+"-v2.vstr");
   try {StructurePackage.load(source);throw new AssertionError("Full fixture unexpectedly admitted");}
   catch(IOException expected) {
    String gate=fixture.equals("city")?"Experimental dependency surface cap":"Experimental geometry cap";
    if(!expected.getMessage().equals(gate))throw expected;
    System.out.println(fixture+": expected rejection: "+gate);
   }
  }
  try(var paths=Files.list(Path.of(System.getProperty("java.io.tmpdir")))) {
   if(paths.anyMatch(p->p.getFileName().toString().startsWith("voxel-structure-import-")))throw new AssertionError("Stage leaked");
  }
  System.out.println("PASS: production full-fixture gates retained; no stages remain");
 }
}
